mapper.select:
SELECT distinct t.r_code1 FROM SYS_RBAC_ROLE_RELATE t INNER JOIN SYS_RBAC_USER T2 ON T.R_CODE1 = T2.USER_O_CODE AND T2.ENABLED = '1' WHERE t.role_code IN
#{roleCode}
AND t.r_type = 'USER'

SELECT t.R_ID,t.ACCOUNT,t.USER_O_CODE,t.USER_O_NAME,t.JY_INSERT_TIME,t.JY_UPDATE_TIME,t.FINANCIER,'0' FLAG,t.ENABLED,null applyId FROM SYS_RBAC_USER t WHERE t.FINANCIER = (
    SELECT p.FINANCIER FROM SYS_RBAC_USER p WHERE p.USER_O_CODE = #{userOCode}
)

    AND T.ACCOUNT LIKE '%' || #{account,jdbcType=VARCHAR} || '%'


    AND T.USER_O_NAME LIKE '%' || #{userOName,jdbcType=VARCHAR} || '%'

SELECT u.USER_O_CODE, listagg(r.ROLE_O_NAME,'|') WITHIN GROUP(ORDER BY u.USER_O_CODE ) as ROLE_O_NAME FROM SYS_RBAC_USER u LEFT JOIN SYS_RBAC_ROLE_RELATE rel ON u.USER_O_CODE = rel.R_CODE1 LEFT JOIN sys_rbac_role r ON rel.ROLE_CODE = r.ROLE_O_CODE WHERE u.USER_O_CODE IN
#{userCode}
GROUP BY u.USER_O_CODE ,u.USER_O_NAME
